-- Generated by tools/generateLiteracyMockQuestionLimits.mjs.
-- V12 short sittings cap the existing route; no item, response or progression threshold changes.
begin;
alter table public.literacy_mock_sessions drop constraint if exists literacy_mock_sessions_item_count_check;
alter table public.literacy_mock_sessions add constraint literacy_mock_sessions_item_count_check
 check((plan_kind='mixed' and item_count in (15,24,25,40,43,67,124)) or (plan_kind='fresh_check' and item_count between 1 and 6));

create or replace function public.lp_mock_session_boundary_schedule(p_session_id uuid,p_rows jsonb,p_states jsonb,p_version text)
returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(value order by position),'[]'::jsonb)
 from jsonb_array_elements(public.lp_mock_boundary_schedule_for_version(p_rows,p_states,p_version)) with ordinality scheduled(value,position)
 where position <= (select item_count from public.literacy_mock_sessions where session_id=p_session_id);
$$;
revoke all on function public.lp_mock_session_boundary_schedule(uuid,jsonb,jsonb,text) from public,anon,authenticated;

create or replace function public.lp_mock_prepare_v12_before_delivery(p_class_id uuid,p_student_ids uuid[] default '{}',
  p_whole_class boolean default false,p_duration_minutes integer default 20,p_item_count integer default 124,p_request_id text default null,p_window_mode text default 'pause_at_window_end')
returns json language plpgsql volatile security definer set search_path='' as $$
declare v_result jsonb; v_id uuid; v_saved public.literacy_mock_preparations; v_hash text; v_version text:='literacy-mock-v12';
begin
  perform public.assert_current_actor_teacher_access();
  if p_window_mode is null or p_window_mode not in ('pause_at_window_end','timed_sample') or p_duration_minutes is null or p_duration_minutes not in (10,20,30,40)
    or p_item_count is null or p_item_count not in (15,25,40,124) then
    return json_build_object('ok',false,'error','invalid_mock_options'); end if;
  if p_request_id is not null and char_length(p_request_id) not between 1 and 160 then
    return json_build_object('ok',false,'error','invalid_request_id'); end if;
  if p_request_id is not null then
    perform pg_advisory_xact_lock(hashtextextended('literacy-mock-prepare:'||auth.uid()::text,0));
    -- The fingerprint contains no recoverable pupil identifiers after deletion.
    v_hash:=encode(sha256(convert_to(jsonb_build_object('classId',p_class_id,'studentIds',p_student_ids,
      'wholeClass',p_whole_class,'minutes',p_duration_minutes,'count',p_item_count,'windowMode',p_window_mode,'version',v_version)::text,'UTF8')),'hex');
    select * into v_saved from public.literacy_mock_preparations where teacher_id=auth.uid() and request_id=p_request_id;
    if found then
      if v_saved.payload_hash<>v_hash then return json_build_object('ok',false,'error','request_conflict'); end if;
      return (public.teacher_get_student_focus_session(v_saved.session_id)::jsonb||jsonb_build_object('duplicate',true))::json;
    end if;
  end if;
  if not exists(select 1 from public.literacy_mock_publications p where p.content_version=v_version and p.available_for_new_sessions
      and p.item_count=(select count(*) from public.literacy_mock_items i where i.content_version=p.content_version)
      and (select count(distinct item->>'domainId') from public.literacy_mock_items i where i.content_version=p.content_version)=8) then
    return json_build_object('ok',false,'error','mock_v12_unavailable'); end if;
  v_result:=public.lp_prepare_literacy_mock_focus(p_class_id,p_student_ids,p_whole_class,v_version);
  if v_result->>'ok'<>'true' then return v_result::json; end if;
  v_id:=(v_result#>>'{session,id}')::uuid;
  insert into public.literacy_mock_sessions(session_id,item_count,duration_seconds,remaining_seconds,window_mode,fresh_sampling)
    values(v_id,p_item_count,p_duration_minutes*60,p_duration_minutes*60,p_window_mode,true);
  if p_request_id is not null then insert into public.literacy_mock_preparations(teacher_id,request_id,payload_hash,session_id)
    values(auth.uid(),p_request_id,v_hash,v_id); end if;
  return public.teacher_get_student_focus_session(v_id);
end; $$;
revoke all on function public.lp_mock_prepare_v12_before_delivery(uuid,uuid[],boolean,integer,integer,text,text) from public,anon,authenticated;

create or replace function public.lp_mock_boundary_plan_error_v9(p_session_id uuid,p_student_id uuid,p_plan jsonb,p_old_plan jsonb,p_answered integer,p_failures jsonb)
returns text language plpgsql stable security definer set search_path='' as $$
declare v_version text:=(select content_version from public.student_focus_sessions where id=p_session_id); v_rows jsonb:=public.lp_mock_boundary_rows_v9(p_session_id,p_student_id); v_reserved jsonb; v_states jsonb; v_schedule jsonb;
 v_id text; v_index integer; v_item jsonb; v_old jsonb; v_current jsonb; v_domain text; v_band integer; v_expected integer;
 v_limit integer; v_ordinals jsonb:='{}'; v_first jsonb:='{}'; v_ordinal integer; v_shown boolean:=false; v_repair boolean:=false;
begin
 select item_count into v_limit from public.literacy_mock_sessions where session_id=p_session_id;
 if v_limit is null then return 'invalid_plan'; end if;
 if p_answered<>jsonb_array_length(v_rows) or jsonb_typeof(p_plan->'itemIds') is distinct from 'array'
  or jsonb_array_length(p_plan->'itemIds') not between p_answered and v_limit then return 'invalid_plan'; end if;
 v_states:=public.lp_mock_boundary_state_for_version(v_rows,v_version); v_reserved:=v_rows;
 if p_old_plan is not null then
  select item into v_current from public.literacy_mock_items where content_version=v_version and id=p_old_plan->'itemIds'->>p_answered;
  v_shown:=v_current is not null and exists(select 1 from public.literacy_mock_events where session_id=p_session_id and student_id=p_student_id and question_id=v_current->>'id' and event_type='presented');
  if v_current is not null and (v_shown or public.lp_literacy_mock_item_blocked(v_current,p_failures)) then
   v_reserved:=v_rows||jsonb_build_array(jsonb_build_object('questionId',v_current->'id','itemSnapshot',v_current->'itemSnapshot','responseStatus','skipped','evidenceType','unscored','isCorrect',null));
  end if;
  -- Media/content repair is a separate transition, preserving every other
  -- slot and the exact failed task before ordinary adaptation resumes.
  if jsonb_array_length(p_plan->'itemIds')=jsonb_array_length(p_old_plan->'itemIds') and p_plan->'itemIds' is distinct from p_old_plan->'itemIds' then
   v_repair:=true;
   for v_id,v_index in select value,ordinality::integer from jsonb_array_elements_text(p_plan->'itemIds') with ordinality loop
    if v_id=p_old_plan->'itemIds'->>(v_index-1) then continue; end if;
    select item into v_old from public.literacy_mock_items where content_version=v_version and id=p_old_plan->'itemIds'->>(v_index-1);
    select item into v_item from public.literacy_mock_items where content_version=v_version and id=v_id;
    if v_index<=p_answered or v_item is null or not (public.lp_literacy_mock_item_blocked(v_old,p_failures) or public.lp_literacy_item_quarantined(v_old))
     or public.lp_literacy_mock_conditions(v_item) is distinct from public.lp_literacy_mock_conditions(v_old)
     or public.lp_mock_area_band(v_item) is distinct from public.lp_mock_area_band(v_old)
     or public.lp_literacy_item_quarantined(v_item) or public.lp_literacy_mock_item_blocked(v_item,p_failures)
     or v_item#>>'{itemSnapshot,adaptiveMixedEligible}' is distinct from 'true' then v_repair:=false; exit; end if;
   end loop;
   if v_repair then return null; end if;
  end if;
 end if;
 v_schedule:=public.lp_mock_session_boundary_schedule(p_session_id,v_reserved,
  case when v_reserved=v_rows then v_states else public.lp_mock_boundary_state_for_version(v_reserved,v_version) end,v_version);
 if jsonb_array_length(p_plan->'itemIds')<>jsonb_array_length(v_schedule) then return 'invalid_plan'; end if;
 for v_id,v_index in select value,ordinality::integer from jsonb_array_elements_text(p_plan->'itemIds') with ordinality loop
  select item into v_item from public.literacy_mock_items where content_version=v_version and id=v_id;
  v_domain:=v_schedule->>(v_index-1); v_band:=public.lp_mock_area_band(v_item);
  if v_item is null or v_item->>'domainId' is distinct from v_domain or v_band is null
   or v_item#>>'{itemSnapshot,adaptiveAreaVersion}' is distinct from (case when v_version in ('literacy-mock-v11','literacy-mock-v12') then 'areas-v6' else 'areas-v5' end)
   or v_item#>>'{itemSnapshot,adaptiveMixedEligible}' is distinct from 'true' then return 'invalid_area_plan'; end if;
  v_ordinal:=coalesce((v_ordinals->>v_domain)::integer,0)+1; v_ordinals:=v_ordinals||jsonb_build_object(v_domain,v_ordinal);
  if v_index<=p_answered then
   if v_id is distinct from v_rows->(v_index-1)->>'questionId' then return 'plan_conflict'; end if;
   continue;
  end if;
  if not v_first ? v_domain then
   v_first:=v_first||jsonb_build_object(v_domain,true); v_expected:=(v_states#>>array[v_domain,'nextBand'])::integer;
  else v_expected:=case when v_version in ('literacy-mock-v11','literacy-mock-v12') then public.lp_mock_placeholder_band_v11(v_domain,v_ordinal) else case when v_domain='print' and v_ordinal>5 then 2 else 0 end end;
  end if;
  if v_index=p_answered+1 and jsonb_array_length(v_reserved)>p_answered then
   if v_id is distinct from v_current->>'id' then return 'presented_item_frozen'; end if;
   v_expected:=public.lp_mock_area_band(v_current);
  end if;
  if v_band is distinct from v_expected then return case when p_old_plan is null then 'invalid_entry_level' else 'invalid_adaptation' end; end if;
 end loop;
 return null;
end; $$;
revoke all on function public.lp_mock_boundary_plan_error_v9(uuid,uuid,jsonb,jsonb,integer,jsonb) from public,anon,authenticated;

create or replace function public.student_record_literacy_mock_event(p_token text,p_session_id uuid,p_question_id text,p_event text,p_request_id text)
returns json language plpgsql volatile security definer set search_path='' as $$
declare v_student public.students; v_mock jsonb; v_run public.literacy_mock_runs; v_event public.literacy_mock_events;
 v_item jsonb; v_payload jsonb; v_familiarity jsonb; v_rows jsonb; v_states jsonb;
begin
 v_student:=public.student_from_token(p_token);
 if v_student.id is null then return json_build_object('ok',false,'error','invalid_session'); end if;
 perform 1 from public.students where id=v_student.id for share;
 if not public.lp_literacy_mock_assignment(v_student.id,p_session_id) then return json_build_object('ok',false,'error','assignment_not_found'); end if;
 if p_event is null or p_event not in ('presented','help_requested','help_cancelled') or coalesce(char_length(p_question_id),0) not between 1 and 240
  or coalesce(char_length(p_request_id),0) not between 1 and 160 then return json_build_object('ok',false,'error','invalid_event'); end if;
 v_mock:=public.lp_literacy_mock_state(p_session_id);
 if v_mock->>'content_version' not in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11','literacy-mock-v12') then return json_build_object('ok',false,'error','unsupported_event_version'); end if;
 select * into v_run from public.literacy_mock_runs where session_id=p_session_id and student_id=v_student.id for update;
 if not found then return json_build_object('ok',false,'error','plan_required'); end if;
 select * into v_event from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id and actor_key='student' and request_id=p_request_id;
 if found then
  if v_event.event_type<>p_event or v_event.question_id<>p_question_id then return json_build_object('ok',false,'error','request_conflict'); end if;
  return json_build_object('ok',true,'duplicate',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id));
 end if;
 -- Repeated render callbacks are a single offer, not additional familiarity.
 if p_event='presented' and exists(select 1 from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id and question_id=p_question_id and event_type='presented') then
  return json_build_object('ok',true,'duplicate',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id)); end if;
 if v_mock->>'state'<>'running' or v_run.status='completed' then return json_build_object('ok',false,'error','assessment_not_running','mock',v_mock); end if;
 if p_question_id is distinct from v_run.plan->'itemIds'->>jsonb_array_length(v_run.responses) then return json_build_object('ok',false,'error','question_not_current'); end if;
 if not exists(select 1 from public.student_focus_session_members where session_id=p_session_id and student_id=v_student.id and active) then
  return json_build_object('ok',false,'error','assignment_not_found'); end if;
 select item into v_item from public.literacy_mock_items where content_version=v_mock->>'content_version' and id=p_question_id;
 if public.lp_literacy_item_quarantined(v_item) then return json_build_object('ok',false,'error','content_item_withdrawn'); end if;
 if v_item is null or public.lp_literacy_mock_item_blocked(v_item,v_run.media_failures) then return json_build_object('ok',false,'error','blocked_media_item'); end if;
 if v_mock->>'content_version' in ('literacy-mock-v9','literacy-mock-v10','literacy-mock-v11','literacy-mock-v12') and p_event='presented' then
  -- One current canonical/support projection serves all three guards. No
  -- projection survives this request; later assistance is read again.
  v_rows:=public.lp_mock_boundary_rows_v9(p_session_id,v_student.id);
  v_states:=public.lp_mock_boundary_state_for_version(v_rows,v_mock->>'content_version');
  if (v_states#>>array[v_item->>'domainId','complete'])::boolean
   or public.lp_mock_session_boundary_schedule(p_session_id,v_rows,v_states,v_mock->>'content_version')->>jsonb_array_length(v_run.responses) is distinct from v_item->>'domainId'
   or public.lp_mock_area_band(v_item) is distinct from (v_states#>>array[v_item->>'domainId','nextBand'])::integer then
   return json_build_object('ok',false,'error','invalid_adaptation'); end if;
 elsif v_mock->>'content_version' in ('literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8') and p_event='presented'
  and public.lp_mock_area_band(v_item) is distinct from public.lp_mock_area_next_band(p_session_id,v_student.id,v_item->>'domainId') then
  return json_build_object('ok',false,'error','invalid_adaptation'); end if;
 if p_event in ('help_requested','help_cancelled') and not exists(select 1 from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id and question_id=p_question_id and event_type='presented') then
  return json_build_object('ok',false,'error','presentation_required'); end if;
 if p_event='help_cancelled' and public.lp_literacy_mock_help(p_session_id,v_student.id,p_question_id)->>'pending'<>'true' then
  return json_build_object('ok',false,'error','help_not_pending'); end if;
 if (select count(*) from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id)>=512 then
  return json_build_object('ok',false,'error','event_limit'); end if;
 v_familiarity:=public.lp_literacy_familiarity(v_student.id,v_item);
 v_payload:=public.lp_literacy_exposure_identity(v_item)||jsonb_build_object('questionId',p_question_id,
  'skillId',v_item->>'skillId','domainId',v_item->>'domainId','level',v_item->'level','itemSnapshot',v_item->'itemSnapshot',
  'presentationStatus','presented','knownFamiliar',case when jsonb_array_length(v_familiarity)>0 then 'true'::jsonb else 'null'::jsonb end,
  'familiarityReasons',v_familiarity);
 insert into public.literacy_mock_events(session_id,student_id,question_id,actor_key,request_id,event_type,payload)
  values(p_session_id,v_student.id,p_question_id,'student',p_request_id,p_event,case when p_event='presented' then v_payload else '{}'::jsonb end);
 return json_build_object('ok',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id));
end; $$;
revoke all on function public.student_record_literacy_mock_event(text,uuid,text,text,text) from public,anon,authenticated;
grant execute on function public.student_record_literacy_mock_event(text,uuid,text,text,text) to anon,authenticated;
notify pgrst,'reload schema';
commit;
